insert into public.quizzes (
  slug, title, question, quiz_type, option_1, option_2, option_3, option_4, correct_answer,
  short_explanation, full_explanation, detail_explanation, example_text, misconception_text, aha_point,
  category_id, difficulty, reading_time, tags, seo_title, seo_description, view_count, is_published, published_at
) values
('ice-floats-water', '얼음은 왜 물에 뜰까?', '얼음이 물에 뜨는 이유는 무엇일까요?', 'MULTIPLE', '얼음 안에 공기가 많아서만', '얼음의 밀도가 액체 물보다 낮아서', '차가운 물이 밀어 올려서', '물의 색이 투명해서', '얼음의 밀도가 액체 물보다 낮아서', '물이 얼 때 분자 배열이 벌어져 부피가 커지고 밀도가 낮아집니다.', '물은 얼면서 부피가 늘어나는 독특한 물질입니다. 물 분자는 수소 결합으로 서로 연결되며 얼음 상태에서는 빈 공간이 있는 결정 구조를 만듭니다. 그래서 같은 질량이라도 얼음은 액체 물보다 부피가 크고 밀도는 낮습니다. 밀도가 낮은 물체는 더 높은 밀도의 액체 위에 뜨므로 얼음은 물 위에 떠 있습니다.', '물은 약 4도에서 밀도가 가장 높아 겨울 호수의 온도 분포에도 영향을 줍니다.', '컵에 얼음을 넣으면 음료 위에 떠서 표면부터 차갑게 만듭니다.', '얼음이 공기 때문에만 뜬다는 설명은 정확하지 않습니다.', '얼음이 뜨는 이유는 물 분자의 배열이 만든 낮은 밀도입니다.', '00000000-0000-0000-0000-000000000002', 'easy', 1, array['얼음','물','밀도','수소 결합'], '얼음은 왜 물에 뜰까? | 오늘의 아하!', '얼음이 물에 뜨는 이유를 밀도와 물 분자 구조로 알아봅니다.', 980, true, '2026-05-24T00:00:00Z'),
('qr-code-stores-info', 'QR코드는 어떻게 정보를 저장할까?', 'QR코드의 검은색과 흰색 작은 칸은 무엇을 나타낼까요?', 'MULTIPLE', '빛의 온도', '0과 1로 읽을 수 있는 데이터 패턴', '카메라 회사의 고유 표시', '인터넷 신호의 세기', '0과 1로 읽을 수 있는 데이터 패턴', 'QR코드는 작은 칸의 배열로 문자, 숫자, URL 같은 데이터를 표현합니다.', 'QR코드는 격자 안의 검은 칸과 흰 칸을 이용해 데이터를 담습니다. 스마트폰 카메라는 큰 위치 표시를 찾아 코드의 방향과 크기를 파악하고 내부 패턴을 읽어 숫자와 문자로 복원합니다. URL을 저장한 QR코드를 찍으면 코드 안에 들어 있던 주소 문자열을 앱이 읽고 브라우저로 여는 것입니다. 일부 칸이 가려져도 읽히는 이유는 오류 정정 정보가 함께 들어 있기 때문입니다.', 'QR코드는 버전과 오류 정정 수준에 따라 담을 수 있는 정보량이 달라집니다.', '식당 메뉴 QR은 대개 메뉴 페이지 URL을 저장합니다.', 'QR코드가 항상 개인정보를 직접 담고 있는 것은 아닙니다.', 'QR코드는 카메라가 읽는 2차원 데이터 표입니다.', '00000000-0000-0000-0000-000000000004', 'easy', 1, array['QR코드','데이터','URL','오류 정정'], 'QR코드는 어떻게 정보를 저장할까? | 오늘의 아하!', 'QR코드의 검은 칸과 흰 칸이 데이터를 표현하는 방식을 설명합니다.', 1670, true, '2026-05-25T00:00:00Z'),
('interest-rate-loan', '금리가 오르면 대출 이자는 왜 늘어날까?', '금리 상승이 대출 이자 부담을 키우는 이유는 무엇일까요?', 'MULTIPLE', '은행 건물이 커져서', '빌린 돈에 적용되는 이자율이 올라서', '통장 색이 바뀌어서', '현금 무게가 늘어서', '빌린 돈에 적용되는 이자율이 올라서', '대출 이자는 원금에 이자율을 곱해 계산되므로 적용 금리가 오르면 부담도 커집니다.', '금리는 돈을 빌리는 비용입니다. 변동금리 대출처럼 시장 금리 변화가 반영되는 상품은 기준금리나 조달금리가 오를 때 대출 금리도 함께 오를 수 있습니다. 같은 원금을 빌렸더라도 적용 이자율이 높아지면 매달 내야 하는 이자액이 늘어납니다. 고정금리 상품은 약정 기간 동안 금리가 비교적 고정되지만 새로 대출을 받거나 갱신할 때는 당시 시장 금리 영향을 받을 수 있습니다.', '월 상환액은 금리, 원금, 만기, 상환 방식에 따라 달라집니다.', '주택담보대출은 금리가 조금만 움직여도 월 부담 차이가 커질 수 있습니다.', '금리가 올라도 모든 대출자의 납입액이 즉시 똑같이 오르는 것은 아닙니다.', '금리는 돈의 가격이고 대출 이자는 그 가격을 매달 치르는 방식입니다.', '00000000-0000-0000-0000-000000000003', 'easy', 1, array['금리','대출','이자','경제'], '금리가 오르면 대출 이자는 왜 늘어날까? | 오늘의 아하!', '금리와 대출 이자의 관계를 쉬운 퀴즈로 확인합니다.', 1330, true, '2026-05-26T00:00:00Z'),
('salt-food-spoil', '소금은 왜 식품을 오래 보관하게 할까?', '소금이 식품 보존에 도움을 주는 대표적인 이유는 무엇일까요?', 'MULTIPLE', '미생물이 이용할 물을 줄여서', '음식을 차갑게 만들어서', '색을 모두 없애서', '공기를 무겁게 만들어서', '미생물이 이용할 물을 줄여서', '소금은 수분 활동도를 낮춰 미생물이 자라기 어려운 환경을 만듭니다.', '음식이 상하는 큰 이유 중 하나는 미생물의 증식입니다. 소금은 삼투압 작용으로 식품과 미생물 주변의 물을 끌어당겨 미생물이 활용할 수 있는 물의 양을 줄입니다. 그래서 젓갈, 장아찌, 절임 식품처럼 짠 음식은 상대적으로 오래 보관될 수 있습니다. 다만 소금이 모든 미생물을 완전히 없애는 것은 아니며 농도와 온도, 산도, 위생 상태가 함께 중요합니다.', '식품 보존에서는 미생물이 이용할 수 있는 물의 정도가 중요합니다.', '김치를 담글 때 배추를 절이면 수분이 빠지고 조직이 달라집니다.', '소금을 넣으면 어떤 음식이든 영원히 안전하다는 생각은 위험합니다.', '소금의 보존 효과는 미생물이 쓸 수 있는 물을 줄이는 데서 시작합니다.', '00000000-0000-0000-0000-000000000001', 'normal', 1, array['소금','식품 보존','미생물','삼투압'], '소금은 왜 식품을 오래 보관하게 할까? | 오늘의 아하!', '소금이 식품 보존에 도움을 주는 원리를 알아봅니다.', 870, true, '2026-05-27T00:00:00Z'),
('soap-removes-oil', '비누는 어떻게 기름때를 씻을까?', '비누가 기름때를 제거하는 이유는 무엇일까요?', 'MULTIPLE', '비누가 기름을 작게 감싸 물에 섞이게 해서', '비누가 손을 뜨겁게 만들어서', '기름을 전부 얼려서', '물의 색을 바꿔서', '비누가 기름을 작게 감싸 물에 섞이게 해서', '비누 분자는 물과 친한 부분, 기름과 친한 부분을 함께 가져 기름때를 분산시킵니다.', '기름은 물과 잘 섞이지 않습니다. 비누 분자는 한쪽은 물과 친하고 다른 한쪽은 기름과 친한 구조를 가집니다. 기름과 친한 부분이 기름때에 붙고 물과 친한 부분이 바깥을 향하면서 작은 덩어리로 감싸면 물에 씻겨 내려가기 쉬워집니다. 이 작은 덩어리를 미셀이라고 부릅니다. 손을 충분히 문지르고 헹구는 과정이 중요한 이유도 여기에 있습니다.', '세정력은 비누의 종류, 물의 온도, 기름의 양, 문지르는 시간에 따라 달라집니다.', '기름진 프라이팬에 세제를 묻혀 문지르면 물만 쓸 때보다 잘 지워집니다.', '비누가 기름을 사라지게 하는 것이 아니라 씻겨 나가도록 분산시키는 것입니다.', '비누는 물과 기름 사이를 이어주는 작은 중개자입니다.', '00000000-0000-0000-0000-000000000001', 'easy', 1, array['비누','기름때','미셀','세정'], '비누는 어떻게 기름때를 씻을까? | 오늘의 아하!', '비누가 기름때를 제거하는 원리를 쉽게 알아봅니다.', 1420, true, '2026-05-28T00:00:00Z'),
('coffee-sleep', '커피를 마시면 왜 잠이 덜 올까?', '커피 속 카페인이 졸음을 줄이는 대표적인 원리는 무엇일까요?', 'MULTIPLE', '몸속 산소를 없애서', '졸림 신호인 아데노신 작용을 방해해서', '눈꺼풀을 가볍게 만들어서', '심장을 잠시 멈춰서', '졸림 신호인 아데노신 작용을 방해해서', '카페인은 아데노신 수용체에 결합해 졸림 신호가 느껴지는 것을 줄입니다.', '오래 깨어 있으면 뇌에는 아데노신이라는 물질의 영향이 쌓이고 졸음이 커집니다. 카페인은 아데노신과 비슷한 자리에 결합해 그 신호가 작동하는 것을 방해합니다. 그래서 커피를 마시면 피로가 사라진 것처럼 느껴질 수 있습니다. 하지만 카페인이 피로 자체를 없애는 것은 아니며 효과가 지나가면 밀려 있던 졸림이 다시 느껴질 수 있습니다. 개인마다 분해 속도가 달라 오후 늦게 마신 커피가 밤잠에 영향을 줄 수 있습니다.', '카페인의 반감기는 사람마다 다르지만 몇 시간 단위로 지속됩니다.', '늦은 오후 아메리카노 한 잔이 새벽까지 영향을 주는 사람도 있습니다.', '커피가 잠을 완전히 대체할 수 있다는 생각은 건강한 수면 관리와 거리가 있습니다.', '카페인은 피로를 지우기보다 졸림 신호를 잠시 가립니다.', '00000000-0000-0000-0000-000000000001', 'easy', 1, array['커피','카페인','수면','아데노신'], '커피를 마시면 왜 잠이 덜 올까? | 오늘의 아하!', '카페인이 졸음을 줄이는 원리를 설명합니다.', 1530, true, '2026-05-29T00:00:00Z'),
('placebo-effect-real', '플라시보 효과는 진짜 효과가 있을까?', '효과가 없는 약처럼 보이는 처치도 실제 몸의 반응을 바꿀 수 있을까요?', 'OX', 'O, 일부 반응은 실제로 달라질 수 있다', 'X, 모두 착각일 뿐이다', null, null, 'O, 일부 반응은 실제로 달라질 수 있다', '기대와 맥락은 통증, 불안 같은 주관적 경험과 일부 생리 반응에 영향을 줄 수 있습니다.', '플라시보 효과는 단순한 거짓말이나 상상이 아닙니다. 어떤 처치가 도움이 될 것이라고 기대하면 뇌의 예측, 주의, 감정 조절이 달라지고 통증이나 불안 같은 경험에 실제 변화가 생길 수 있습니다. 의료 연구에서 플라시보 대조군을 두는 이유도 약의 고유 효과와 기대 효과를 구분하기 위해서입니다. 다만 플라시보가 모든 병을 치료하는 것은 아니며 효과의 범위와 한계를 함께 이해해야 합니다.', '플라시보 반응은 의사소통, 치료 환경, 이전 경험, 기대감에 영향을 받습니다.', '진통제라고 믿고 받은 처치가 통증 평가를 낮추는 경우가 연구에서 관찰됩니다.', '플라시보 효과가 있다는 말은 병이 마음 탓이라는 뜻이 아닙니다.', '기대는 몸의 경험을 바꿀 수 있지만 치료의 전부는 아닙니다.', '00000000-0000-0000-0000-000000000005', 'normal', 1, array['플라시보','심리','기대 효과','통증'], '플라시보 효과는 진짜 효과가 있을까? | 오늘의 아하!', '플라시보 효과가 실제로 어떤 반응을 바꾸는지 알아봅니다.', 1760, true, '2026-05-30T00:00:00Z')
on conflict (slug) do nothing;

insert into public.quizzes (
  slug, title, question, quiz_type, option_1, option_2, option_3, option_4, correct_answer,
  short_explanation, full_explanation, detail_explanation, example_text, misconception_text, aha_point,
  category_id, difficulty, reading_time, tags, seo_title, seo_description, view_count, is_published, published_at
) values
('zero-drink-bugs', '제로콜라 같은 제로 음료에도 벌레가 꼬일까?', '설탕이 거의 없는 제로 음료에도 초파리나 벌레가 꼬일 수 있을까요?', 'OX', 'O, 꼬일 수 있다', 'X, 설탕이 없으면 꼬이지 않는다', null, null, 'O, 꼬일 수 있다', '제로 음료에도 향, 산미, 첨가물, 용기 주변 잔여물 때문에 벌레가 접근할 수 있습니다.', '벌레는 설탕만 보고 움직이지 않습니다. 초파리는 발효 냄새, 과일 향, 산성 향, 젖은 표면, 음료가 묻은 병 입구 같은 단서를 함께 감지합니다. 그래서 제로 음료 벌레 현상은 충분히 일어날 수 있습니다. 마시다 남은 음료는 침, 공기 중 미생물, 컵 주변의 음식물 흔적과 섞이며 냄새가 달라질 수 있습니다. 벌레 꼬임을 줄이려면 마시던 음료를 오래 방치하지 않고 캔 입구와 컵 주변을 헹구며 음식물 쓰레기와 함께 두지 않는 편이 좋습니다.', '감미료는 설탕과 다르지만 음료의 향료와 산도는 벌레에게 충분한 탐색 신호가 될 수 있습니다.', '캔을 딴 뒤 책상 위에 오래 두면 음료 자체보다 입구와 주변 냄새가 벌레를 부를 수 있습니다.', '제로 음료는 칼로리가 낮으니 벌레도 절대 관심이 없다는 생각은 지나친 단순화입니다.', '벌레는 설탕만이 아니라 냄새와 환경 신호를 함께 따라옵니다.', '00000000-0000-0000-0000-000000000001', 'easy', 1, array['제로콜라 벌레','제로 음료 벌레','초파리','벌레 꼬임','마시다 남은 음료'], '제로콜라 같은 제로 음료에도 벌레가 꼬일까? | 오늘의 아하!', '제로 음료에도 초파리나 벌레가 꼬일 수 있을까요? O/X 퀴즈로 확인하고 이유를 알아봅니다.', 1820, true, '2026-05-21T00:00:00Z'),
('microwave-food-heat', '전자레인지는 음식을 안쪽부터 데울까?', '전자레인지는 음식을 항상 안쪽부터 익힌다는 말이 맞을까요?', 'OX', 'O, 항상 안쪽부터 데운다', 'X, 음식과 조건에 따라 다르다', null, null, 'X, 음식과 조건에 따라 다르다', '마이크로파는 음식 속 물 분자를 흔들지만 침투 깊이와 모양 때문에 열 분포가 달라집니다.', '전자레인지는 마이크로파로 음식 속 분자를 움직이게 해 열을 만듭니다. 그렇다고 모든 음식이 안쪽부터 데워지는 것은 아닙니다. 음식의 두께, 수분량, 소금 농도, 그릇 모양, 회전판 위치에 따라 뜨거운 곳과 차가운 곳이 생깁니다. 국물은 섞으면 열이 퍼지지만 두꺼운 고기나 냉동밥은 가운데가 늦게 데워질 수 있습니다.', '표면과 내부에서 동시에 열이 만들어지고 이후 열전도와 대류가 전체 온도를 바꿉니다.', '냉동 볶음밥을 데울 때 중간에 섞으면 차가운 덩어리가 줄어듭니다.', '전자레인지가 음식의 중심만 골라 데운다는 설명은 정확하지 않습니다.', '전자레인지 조리는 음식 속 조건이 만든 열 분포의 문제입니다.', '00000000-0000-0000-0000-000000000002', 'normal', 1, array['전자레인지','마이크로파','음식 데우기'], '전자레인지는 음식을 안쪽부터 데울까? | 오늘의 아하!', '전자레인지가 음식을 데우는 원리와 차가운 부분이 생기는 이유를 알아봅니다.', 1210, true, '2026-05-22T00:00:00Z'),
('why-sky-blue', '하늘은 왜 파랗게 보일까?', '맑은 낮 하늘이 파랗게 보이는 가장 큰 이유는 무엇일까요?', 'MULTIPLE', '바다가 하늘에 비쳐서', '공기가 파란색이라서', '짧은 파장의 빛이 더 많이 산란돼서', '태양이 파란빛을 가장 많이 내서', '짧은 파장의 빛이 더 많이 산란돼서', '공기 분자는 파장이 짧은 파란빛을 상대적으로 더 강하게 산란시킵니다.', '햇빛은 여러 색의 빛이 섞여 있습니다. 그 빛이 대기를 지나올 때 공기 분자와 작은 입자에 부딪혀 여러 방향으로 흩어지는데 파장이 짧은 파란빛이 빨간빛보다 더 잘 흩어집니다. 우리는 하늘 여러 방향에서 흩어진 파란빛을 보기 때문에 낮 하늘을 파랗게 느낍니다. 해질 무렵에는 빛이 대기를 더 길게 통과해 노을이 붉게 보입니다.', '이 현상은 레일리 산란으로 설명합니다.', '비가 온 뒤 먼지가 적은 날 하늘이 더 선명하게 보일 수 있습니다.', '하늘색은 바다색이 반사되어 생긴다는 말은 흔하지만 사실이 아닙니다.', '파란 하늘은 햇빛과 대기가 만들어내는 산란 효과입니다.', '00000000-0000-0000-0000-000000000002', 'easy', 1, array['하늘','파란 하늘','레일리 산란','빛'], '하늘은 왜 파랗게 보일까? | 오늘의 아하!', '하늘이 파란 이유와 노을이 붉은 이유를 빛의 산란 원리로 이해합니다.', 2440, true, '2026-05-23T00:00:00Z')
on conflict (slug) do nothing;
